mapper.select:
select a.request_id, a.requester_id, a.receiver_id, a.status, a.created_at, a.updated_at,
b.profile_id as sender_profile_id, b.nickname as sender_nickname, b.stored_name as sender_profile_image ,
c.profile_id as receiver_profile_id, c.nickname as receiver_nickname, c.stored_name as receiver_profile_image from friend_request_tbl a left join profile_tbl b on a.receiver_id = b.user_id left join profile_tbl c on a.requester_id = c.user_id where a.receiver_id = #{userId} and a.status = 'REQUEST';

SELECT
    CASE
        -- 친구 여부
        WHEN EXISTS (
            SELECT 1
            FROM friend_tbl
            WHERE
                (user_id = #{userId}
                    AND friend_user_id = #{checkUserId})
               OR
                (user_id = #{checkUserId}
                    AND friend_user_id = #{userId})
        )
            THEN 'FRIEND'

        -- 내가 보낸 요청
        WHEN EXISTS (
            SELECT 1
            FROM friend_request_tbl
            WHERE requester_id = #{userId}
              AND receiver_id = #{checkUserId}
              AND status = 'REQUEST'
        )
            THEN 'REQUEST'

        -- 상대가 보낸 요청
        WHEN EXISTS (
            SELECT 1
            FROM friend_request_tbl
            WHERE requester_id = #{checkUserId}
              AND receiver_id = #{userId}
              AND status = 'REQUEST'
        )
            THEN 'RECEIVED'
        ELSE 'NONE'
        END AS friendStatus,
    (
        SELECT request_id
        FROM friend_request_tbl
        WHERE
            (
                requester_id = #{userId}
                    AND receiver_id = #{checkUserId}
                )
           OR
            (
                requester_id = #{checkUserId}
                    AND receiver_id = #{userId}
                )
                AND status = 'REQUEST'
        LIMIT 1
    ) AS requestId
